import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(io.StringIO(raw_csv, newline=""),
                              delimiter=",", quotechar='"', doublequote=True))
    expected_width = 4
    if not records:
        return {"columns": [], "rows": []}

    def is_label(value):
        value = value.strip()
        if not value:
            return False
        try:
            float(value)
        except ValueError:
            return True
        return False

    def is_full_header(row):
        return len(row) == expected_width and all(is_label(cell) for cell in row)

    def is_group_header(index):
        if index + 1 >= len(records):
            return False
        groups, labels = records[index:index + 2]
        if len(groups) != expected_width or not is_full_header(labels):
            return False
        starts = [i for i, cell in enumerate(groups) if cell.strip()]
        if not 1 < len(starts) < expected_width or starts[0] != 0:
            return False
        if not all(is_label(groups[i]) for i in starts):
            return False
        ends = starts[1:] + [expected_width]
        signatures = [
            tuple(cell.strip() for cell in labels[start:end])
            for start, end in zip(starts, ends)
        ]
        return len(set(signatures)) == 1

    index = 0
    while index < len(records) and not any(cell.strip() for cell in records[index]):
        index += 1
    if index == len(records):
        return {"columns": [], "rows": []}

    # Skip leading title records only if a recognizable header follows.
    candidate = index
    while candidate < len(records):
        row = records[candidate]
        populated = [cell for cell in row if cell.strip()]
        if not populated or (len(populated) == 1 and is_label(populated[0])):
            candidate += 1
        else:
            break
    if candidate < len(records) and (
        is_group_header(candidate) or is_full_header(records[candidate])
    ):
        index = candidate

    if is_group_header(index):
        groups, labels = records[index:index + 2]
        columns = []
        group = ""
        for heading, label in zip(groups, labels):
            if heading.strip():
                group = heading
            columns.append(group + " " + label)
        index += 2
    else:
        columns = records[index][:]
        index += 1

    rows = records[index:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))
    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = "column_" + str(position)
        name = base
        suffix = 2
        while name in used_names:
            name = base + "_" + str(suffix)
            suffix += 1
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
